from typing import List

class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        max_bits = 70
        n = len(nums)
        bits = [[] for _ in range(n)]
        for i, x in enumerate(nums):
            for j in range(max_bits):
                if (x >> j) & 1:
                    bits[i].append(j)

        bit_count = [0] * max_bits
        for i in range(n):
            for j in bits[i]:
                if j < max_bits:
                    bit_count[j] += 1

        for _ in range(k):
            best_gain = -1
            best_i = -1
            for i in range(n):
                old_bits = bits[i]
                old_bits_valid = [j for j in old_bits if j + 1 < max_bits]
                new_bits = [j + 1 for j in old_bits_valid]

                temp_gain = 0
                for j in old_bits_valid:
                    bit_count[j] -= 1
                    if bit_count[j] == 0:
                        temp_gain -= (1 << j)
                for j in new_bits:
                    bit_count[j] += 1
                    if bit_count[j] == 1:
                        temp_gain += (1 << j)

                for j in old_bits_valid:
                    bit_count[j] += 1
                for j in new_bits:
                    bit_count[j] -= 1

                if temp_gain > best_gain:
                    best_gain = temp_gain
                    best_i = i

            old_bits = bits[best_i]
            old_bits_valid = [j for j in old_bits if j + 1 < max_bits]
            new_bits = [j + 1 for j in old_bits_valid]
            old_val = nums[best_i]
            new_val = old_val * 2
            nums[best_i] = new_val
            bits[best_i] = new_bits

            for j in old_bits_valid:
                bit_count[j] -= 1
            for j in new_bits:
                bit_count[j] += 1

        result = 0
        for j in range(max_bits):
            if bit_count[j] > 0:
                result |= (1 << j)
        return result
```

