                new_dp = [[0] * (max_s + 1) for _ in range(2)]
                for tight in (0, 1):
                    for s_val in range(max_s + 1):
                        cnt = dp[tight][s_val]
                        if cnt == 0:
                            continue
                        upper = digit if tight else 9
                        for d in range(0, upper + 1):
                            new_tight = tight and (d == upper)
                            new_sum = s_val + d
                            if new_sum > max_s:
                                continue
                            new_dp[new_tight][new_sum] = (new_dp[new_tight][new_sum] + cnt) % mod
                dp = new_dp
            total = 0
            for tight in (0, 1):
                for s_val in range(min_s, max_s + 1):
                    total = (total + dp[tight][s_val]) % mod
            return total

        low = str(int(num1) - 1)
        high = num2
        res = (count_up_to(high, min_sum, max_sum) - count_up_to(low, min_sum, max_sum)) % mod
        return res if res >= 0 else res + mod
