class Solution:
    def punishmentNumber(self, n: int) -> int:
        total = 0
        for i in range(1, n + 1):
            sq = i * i
            s = str(sq)
            if self.can_partition(s, i):
                total += sq
        return total

    def can_partition(self, s: str, target: int) -> bool:
        n = len(s)

        def dfs(idx, cur):
            if cur > target:
                return False
            if idx == n:
                return cur == target
            for length in range(1, n - idx + 1):
                if s[idx] == '0' and length > 1:
                    continue
                num = int(s[idx:idx + length])
                if dfs(idx + length, cur + num):
                    return True
            return False

        return dfs(0, 0)
```

