from typing import List

class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True
        if any(x == 1 for x in nums):
            return False

        max_val = 100000
        spf = list(range(max_val + 1))
        for i in range(2, int(max_val**0.5) + 1):
            if spf[i] == i:
                for j in range(i*i, max_val+1, i):
                    if spf[j] == j:
                        spf[j] = i

        parent = {}

        def find(x):
            root = x
            while parent[root] != root:
                root = parent[root]
            while x != root:
                nxt = parent[x]
                parent[x] = root
                x = nxt
            return root

        def union(x, y):
            rx = find(x)
            ry = find(y)
            if rx == ry:
                return
            parent[ry] = rx

        for num in nums:
            temp = num
            factors = set()
            while temp > 1:
                p = spf[temp]
                factors.add(p)
                while temp % p == 0:
                    temp //= p
            primes = list(factors)
            if not primes:
                continue
            for p in primes:
                if p not in parent:
                    parent[p] = p
            root = primes[0]
            for i in range(1, len(primes)):
                union(root, primes[i])

        components = set()
        for p in parent:
            components.add(find(p))
        return len(components) == 1
```

