class Solution:
    def longestEqualSubarray(self, nums: List[int], k: int) -> int:
        pos_dict = defaultdict(list)
        for i, num in enumerate(nums):
            pos_dict[num].append(i)

        best = 0
        for positions in pos_dict.values():
            m = len(positions)
            if m == 0:
                continue
            i_ptr = 0
            for j in range(m):
                while (positions[j] - j) - (positions[i_ptr] - i_ptr) > k:
                    i_ptr += 1
                best = max(best, j - i_ptr + 1)
        return best
