class Solution:
    def longestAlternatingSubarray(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        max_len = 0
        for i in range(n):
            if nums[i] % 2 != 0 or nums[i] > threshold:
                continue
            j = i + 1
            while j < n:
                if nums[j] > threshold:
                    break
                if nums[j] % 2 == nums[j-1] % 2:
                    break
                j += 1
            max_len = max(max_len, j - i)
