            return len(word)
        max_len_forbidden = max(len(f) for f in forbidden)
        forbidden_set = set(forbidden)
        n = len(word)
        l = 0
        max_valid = 0
        for r in range(n):
            for k in range(1, max_len_forbidden + 1):
                start = r - k + 1
                if start < l:
                    break
                substr = word[start:r + 1]
                if substr in forbidden_set:
                    l = max(l, start + 1)
            max_valid = max(max_valid, r - l + 1)
        return max_valid
