class Solution:
    MOD = 10**9 + 7
    max_len = 100
    g = None

    def precompute_g(self):
        if self.g is None:
            self.g = [0] * (self.max_len + 1)
            prev = [0] * 10
            for d in range(1, 10):
                prev[d] = 1
            self.g[1] = 9
            for L in range(2, self.max_len + 1):
                curr = [0] * 10
                for d in range(10):
                    for prev_d in range(10):
                        if abs(d - prev_d) == 1:
                            curr[d] = (curr[d] + prev[prev_d]) % self.MOD
                total = sum(curr) % self.MOD
                self.g[L] = total
                prev = curr

    def subtract_one(self, s):
        arr = list(map(int, list(s)))
        n = len(arr)
        i = n - 1
        while i >= 0 and arr[i] == 0:
            arr[i] = 9
            i -= 1
        if i < 0:
            return "0"
        arr[i] -= 1
        result = ''.join(str(x) for x in arr).lstrip('0')
        return result if result != '' else "0"

    def count_up_to(self, s):
        if s == "0":
            return 0
        n = len(s)
        total = 0
        for L in range(1, n):
            total = (total + self.g[L]) % self.MOD
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def rec(pos, tight, last):
            if pos == n:
                return 1
            total = 0
            upper = int(s[pos]) if tight else 9
            for d in range(0, upper + 1):
                if pos == 0 and d == 0:
                    continue
                if pos == 0:
                    new_tight = tight and (d == upper)
                    total = (total + rec(pos + 1, new_tight, d)) % self.MOD
                else:
                    if abs(d - last) != 1:
                        continue
                    new_tight = tight and (d == upper)
                    total = (total + rec(pos + 1, new_tight, d)) % self.MOD
            return total % self.MOD
        total = (total + rec(0, True, 0)) % self.MOD
        return total

    def countSteppingNumbers(self, low: str, high: str) -> int:
        self.precompute_g()
        low_minus = self.subtract_one(low)
        count_high = self.count_up_to(high)
        count_low = self.count_up_to(low_minus)
        return (count_high - count_low) % self.MOD
```

