class Solution:
    def maximumTripletValue(self, nums: list[int]) -> int:
        n = len(nums)
        max_from = [0] * n
        max_from[-1] = nums[-1]
        for i in range(n - 2, -1, -1):
            max_from[i] = max(nums[i], max_from[i + 1])

        max_so_far = nums[0]
        ans = 0
        for j in range(1, n - 1):
            diff = max_so_far - nums[j]
            candidate = diff * max_from[j + 1]
            if candidate > ans:
                ans = candidate
            if nums[j] > max_so_far:
                max_so_far = nums[j]
        return ans
