class Solution:
    def distributeCandies(self, n: int, limit: int) -> int:
        total = (n + 2) * (n + 1) // 2

        def f(t):
            if t < 0:
                return 0
            return (t + 2) * (t + 1) // 2

        a1 = f(n - (limit + 1))
        ab1 = f(n - 2 * (limit + 1))
        abc1 = f(n - 3 * (limit + 1))

        return total - 3 * a1 + 3 * ab1 - abc1
