class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        n = len(word)
        INF = 10**9
        dp = [[INF] * 26 for _ in range(n)]
        idx0 = ord(word[0]) - ord('a')
        for j in range(26):
            dp[0][j] = 0 if j == idx0 else 1

        for i in range(1, n):
            idx_i = ord(word[i]) - ord('a')
            for j in range(26):
                min_prev = INF
                for k in range(26):
                    if k == j or abs(k - j) == 1:
                        continue
                    if dp[i-1][k] < min_prev:
                        min_prev = dp[i-1][k]
                dp[i][j] = min_prev + (0 if j == idx_i else 1)

        return min(dp[n-1])
