from typing import List

class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        n = len(source)
        if source == target:
            return 0

        INF = 10**18
        dist = [[INF] * 26 for _ in range(26)]

        for i in range(26):
            dist[i][i] = 0

        for i in range(len(original)):
            x = original[i]
            y = changed[i]
            c = cost[i]
            idx_x = ord(x) - ord('a')
            idx_y = ord(y) - ord('a')
            if c < dist[idx_x][idx_y]:
                dist[idx_x][idx_y] = c

        for k in range(26):
            for i in range(26):
                if dist[i][k] == INF:
                    continue
                for j in range(26):
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

        total = 0
        for i in range(n):
            if source[i] != target[i]:
                s = source[i]
                t = target[i]
                idx_s = ord(s) - ord('a')
                idx_t = ord(t) - ord('a')
                if dist[idx_s][idx_t] == INF:
                    return -1
                total += dist[idx_s][idx_t]

        return total
