from typing import List

class Solution:
    def missingInteger(self, nums: List[int]) -> int:
        L = 1
        n = len(nums)
        for i in range(1, n):
            if nums[i] == nums[i-1] + 1:
                L += 1
            else:
                break
        total = sum(nums[:L])
        s = set(nums)
        x = total
        while x in s:
            x += 1
        return x
