class Solution:
    def maximumSubarraySum(self, nums: list[int], k: int) -> int:
        prefix = 0
        min_prefix = {}
        max_sum = -10**18

        for j in range(len(nums)):
            if nums[j] in min_prefix:
                if prefix < min_prefix[nums[j]]:
                    min_prefix[nums[j]] = prefix
            else:
                min_prefix[nums[j]] = prefix

            current_prefix = prefix + nums[j]
            target1 = nums[j] - k
            target2 = nums[j] + k

            if target1 in min_prefix:
                max_sum = max(max_sum, current_prefix - min_prefix[target1])
            if target2 in min_prefix:
                max_sum = max(max_sum, current_prefix - min_prefix[target2])

            prefix = current_prefix

        return max_sum if max_sum != -10**18 else 0
