from collections import Counter

class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        freq = Counter(nums)
        ans = 1
        for x in freq:
            if x == 1:
                m = (freq[x] - 1) // 2
                length = 2 * m + 1
                if length > ans:
                    ans = length
                continue
            current = x
            m = 0
            while True:
                next_val = current * current
                if next_val > 10**9:
                    break
                if freq[current] < 2:
                    break
                if freq.get(next_val, 0) < 1:
                    break
                m += 1
                current = next_val
            length = 1 + 2 * m
            if length > ans:
                ans = length
        return ans
