def main():
    import sys
    data = sys.stdin.read().splitlines()
    n = int(data[0])
    cards = []
    for i in range(1, 1 + n):
        a, b = map(int, data[i].split())
        cards.append((a, b))

    memo = {}

    def can_win(state):
        if state in memo:
            return memo[state]
        moves = []
        for i in range(n):
            if not (state & (1 << i)):
                continue
            for j in range(i + 1, n):
                if not (state & (1 << j)):
                    continue
                if cards[i][0] == cards[j][0] or cards[i][1] == cards[j][1]:
                    moves.append((i, j))
        if not moves:
            memo[state] = False
            return False
        for i, j in moves:
            new_state = state & ~(1 << i) & ~(1 << j)
            if not can_win(new_state):
                memo[state] = True
                return True
        memo[state] = False
        return False

    initial_state = (1 << n) - 1
    print("Takahashi" if can_win(initial_state) else "Aoki")

if __name__ == '__main__':
    main()
