from typing import List

class Solution:
    def stringIndices(self, wordsContainer: List[str], wordsQuery: List[str]) -> List[int]:
        class TrieNode:
            __slots__ = ['children', 'best']
            def __init__(self):
                self.children = {}
                self.best = (10**9, -1)

        root = TrieNode()
        for i, word in enumerate(wordsContainer):
            rev_word = word[::-1]
            length = len(word)
            if length < root.best[0] or (length == root.best[0] and i < root.best[1]):
                root.best = (length, i)
            node = root
            for c in rev_word:
                if c not in node.children:
                    node.children[c] = TrieNode()
                node = node.children[c]
                if length < node.best[0] or (length == node.best[0] and i < node.best[1]):
                    node.best = (length, i)

        ans = []
        for query in wordsQuery:
            rev_query = query[::-1]
            node = root
            for c in rev_query:
                if c not in node.children:
                    break
                node = node.children[c]
            ans.append(node.best[1])
        return ans
