        n = len(points)
        u_vals = [x + y for x, y in points]
        v_vals = [x - y for x, y in points]

        global_max_u = max(u_vals)
        global_min_u = min(u_vals)
        global_max_v = max(v_vals)
        global_min_v = min(v_vals)

        second_max_u = -10**18
        for u in u_vals:
            if u < global_max_u and u > second_max_u:
                second_max_u = u

        second_min_u = 10**18
        for u in u_vals:
            if u > global_min_u and u < second_min_u:
                second_min_u = u

        second_max_v = -10**18
        for v in v_vals:
            if v < global_max_v and v > second_max_v:
                second_max_v = v

        second_min_v = 10**18
        for v in v_vals:
            if v > global_min_v and v < second_min_v:
                second_min_v = v

        count_max_u = sum(1 for u in u_vals if u == global_max_u)
        count_min_u = sum(1 for u in u_vals if u == global_min_u)
        count_max_v = sum(1 for v in v_vals if v == global_max_v)
        count_min_v = sum(1 for v in v_vals if v == global_min_v)

        best = 10**18
        for i in range(n):
            if u_vals[i] == global_max_u:
                new_max_u = second_max_u if count_max_u == 1 else global_max_u
            else:
                new_max_u = global_max_u
            if u_vals[i] == global_min_u:
                new_min_u = second_min_u if count_min_u == 1 else global_min_u
            else:
                new_min_u = global_min_u
            range_u = new_max_u - new_min_u

            if v_vals[i] == global_max_v:
                new_max_v = second_max_v if count_max_v == 1 else global_max_v
            else:
                new_max_v = global_max_v
            if v_vals[i] == global_min_v:
                new_min_v = second_min_v if count_min_v == 1 else global_min_v
            else:
                new_min_v = global_min_v
            range_v = new_max_v - new_min_v

            candidate = max(range_u, range_v)
            if candidate < best:
                best = candidate

        return best
