MOD = 10**9 + 7

class Solution:
    def sumOfPowers(self, nums: list[int], k: int) -> int:
        n = len(nums)
        nums.sort()
        diffs = set()
        for i in range(n):
            for j in range(i + 1, n):
                diffs.add(nums[j] - nums[i])
        D = sorted(diffs)

        def count_subsets(a, k_val, t_val):
            n_val = len(a)
            if k_val == 0:
                return 0
            dp = [[0] * (k_val + 1) for _ in range(n_val)]
            prefix = [[0] * n_val for _ in range(k_val + 1)]

            for i in range(n_val):
                dp[i][1] = 1
                prefix[1][i] = (dp[i][1] + (prefix[1][i - 1] if i - 1 >= 0 else 0)) % MOD

            if k_val == 1:
                total = 0
                for i in range(n_val):
                    total = (total + dp[i][1]) % MOD
                return total

            for j in range(2, k_val + 1):
                for i in range(n_val):
                    if i < j - 1:
                        dp[i][j] = 0
                        prefix[j][i] = (dp[i][j] + (prefix[j][i - 1] if i - 1 >= 0 else 0)) % MOD
                    else:
                        low, high = 0, i - 1
                        p_max = -1
                        while low <= high:
                            mid = (low + high) // 2
                            if a[mid] <= a[i] - t_val:
                                p_max = mid
                                low = mid + 1
                            else:
                                high = mid - 1
                        s = prefix[j - 1][p_max] if p_max != -1 else 0
                        dp[i][j] = s % MOD
                        prefix[j][i] = (dp[i][j] + (prefix[j][i - 1] if i - 1 >= 0 else 0)) % MOD

            total = 0
            for i in range(n_val):
                total = (total + dp[i][k_val]) % MOD
            return total

        F_dict = {}
        for t_val in D:
            F_dict[t_val] = count_subsets(nums, k, t_val)

        total_ans = 0
        for i in range(len(D)):
            d = D[i]
            next_d = D[i + 1] if i + 1 < len(D) else None
            cnt = F_dict[d] - (F_dict[next_d] if next_d is not None else 0)
            total_ans = (total_ans + d * cnt) % MOD

        return total_ans % MOD
