class Solution:
    def waysToReachStair(self, k: int) -> int:
        def nCr(n, r):
            if r < 0 or r > n:
                return 0
            r = min(r, n - r)
            num = 1
            for i in range(1, r + 1):
                num = num * (n - i + 1) // i
            return num

        total = 0
        u = 0
        while True:
            power = 1 << u
            if power < k:
                u += 1
                continue
            if power > k + u + 1:
                break
            d = power - k
            if 0 <= d <= u + 1:
                total += nCr(u + 1, d)
            u += 1
        return total
