class Solution:
    def findProductsOfElements(self, queries: List[List[int]]) -> List[int]:
        def total_ones(n):
            if n == 0:
                return 0
            count = 0
            i = 0
            while (1 << i) <= n:
                divisor = 1 << (i + 1)
                remainder = n + 1
                count += (remainder // divisor) * (1 << i)
                remainder %= divisor
                count += max(0, remainder - (1 << i))
                i += 1
            return count

        def count_bit_set(x, b):
            if x == 0:
                return 0
            divisor = 1 << (b + 1)
            remainder = x + 1
            count = (remainder // divisor) * (1 << b)
            remainder %= divisor
            count += max(0, remainder - (1 << b))
            return count

        def G(x):
            if x == 0:
                return 0
            total = 0
            for b in range(0, 61):
                cnt = count_bit_set(x, b)
                total += b * cnt
            return total

        def find_x(pos):
            if pos < 0:
                return 0
            low, high = 1, pos + 1
            while low < high:
                mid = (low + high) // 2
                if total_ones(mid) > pos:
                    high = mid
                else:
                    low = mid + 1
            return low

        def F(pos):
            if pos < 0:
                return 0
            x = find_x(pos)
            prev_len = total_ones(x - 1)
            p = pos - prev_len
            bits = []
            for b in range(0, 61):
                if x & (1 << b):
                    bits.append(b)
            sum_p = sum(bits[:p + 1])
            return G(x - 1) + sum_p

        res = []
        for q in queries:
            L, R, mod = q
            S = F(R) - F(L - 1)
            res.append(pow(2, S, mod))
        return res
