class Solution:
    def minimumDifference(self, nums: List[int], k: int) -> int:
        n = len(nums)
        totalOR = 0
        for x in nums:
            totalOR |= x

        next_occ = [[n] * n for _ in range(32)]

        for b in range(32):
            last = n
            for i in range(n-1, -1, -1):
                if (nums[i] >> b) & 1:
                    last = i
                next_occ[b][i] = last

        min_diff = float('inf')

        for left in range(n):
            cur = 0
            r = left
            while r < n:
                cur |= nums[r]
                if abs(k - cur) < min_diff:
                    min_diff = abs(k - cur)
                if cur == totalOR:
                    break
                next_r = n
                for b in range(32):
                    if (cur >> b) & 1:
                        continue
                    if r + 1 < n:
                        pos = next_occ[b][r+1]
                        if pos < n and pos < next_r:
                            next_r = pos
                if next_r == n:
                    break
                r = next_r

        return min_diff
