        mod = 10**9 + 7
        n = len(nums)
        if n == 0:
            return 0
        max_val = max(nums)
        dp = [0] * (max_val + 1)
        for a in range(nums[0] + 1):
            dp[a] = 1

        for i in range(1, n):
            prefix = [0] * (max_val + 1)
            prefix[0] = dp[0]
            for j in range(1, max_val + 1):
                prefix[j] = (prefix[j-1] + dp[j]) % mod

            new_dp = [0] * (max_val + 1)
            diff = nums[i] - nums[i-1]
            for a in range(nums[i] + 1):
                if diff >= 0:
                    high = a - diff
                else:
                    high = a
                if high < 0:
                    new_dp[a] = 0
                else:
                    new_dp[a] = prefix[high]
            dp = new_dp

        total = sum(dp) % mod
        return total
