class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        prefix = [0] * (n + 1)
        for i in range(1, n + 1):
            prefix[i] = prefix[i - 1] + (1 if s[i - 1] == '0' else 0)

        total = 0
        for i in range(n):
            for j in range(i, n):
                length = j - i + 1
                zeros = prefix[j + 1] - prefix[i]
                ones = length - zeros
                if zeros <= k or ones <= k:
                    total += 1
        return total
