    def countPairs(self, nums: List[int]) -> int:
        from typing import List
        cache = {}
        def reachableSet(x):
            if x in cache:
                return cache[x]
            s = str(x)
            n = len(s)
            res = {x}
            for i in range(n):
                for j in range(i + 1, n):
                    lst = list(s)
                    lst[i], lst[j] = lst[j], lst[i]
                    new_str = ''.join(lst)
                    res.add(int(new_str))
            cache[x] = res
            return res

        count = 0
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                a, b = nums[i], nums[j]
                if b in reachableSet(a) or a in reachableSet(b):
                    count += 1
        return count
