from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        class LiChaoTree:
            def __init__(self, low, high):
                self.low = low
                self.high = high
                self.tree = [None] * (4 * (high - low + 1))

            def f(self, line, x):
                return line[0] * x + line[1]

            def update(self, m, c):
                self._update(1, self.low, self.high, m, c)

            def _update(self, node, l, r, m, c):
                if l == r:
                    if self.tree[node] is None or self.f((m, c), l) > self.f(self.tree[node], l):
                        self.tree[node] = (m, c)
                    return
                mid = (l + r) // 2
                if self.tree[node] is None:
                    self.tree[node] = (m, c)
                    return
                if self.f((m, c), mid) > self.f(self.tree[node], mid):
                    self.tree[node], m, c = (m, c), self.tree[node][0], self.tree[node][1]
                if self.f((m, c), l) > self.f(self.tree[node], l):
                    self._update(2 * node, l, mid, m, c)
                else:
                    self._update(2 * node + 1, mid + 1, r, m, c)

            def query(self, x):
                return self._query(1, self.low, self.high, x)

            def _query(self, node, l, r, x):
                if l == r:
                    return self.f(self.tree[node], x) if self.tree[node] is not None else -10**30
                mid = (l + r) // 2
                res = -10**30
                if self.tree[node] is not None:
                    res = self.f(self.tree[node], x)
                if x <= mid:
                    res = max(res, self._query(2 * node, l, mid, x))
                else:
                    res = max(res, self._query(2 * node + 1, mid + 1, r, x))
                return res

        n = len(nums)
        if n == 1:
            return 0
        dp = [0] * n
        dp[n - 1] = 0
        low, high = 1, 100000
        tree = LiChaoTree(low, high)
        tree.update(n - 1, 0)
        for i in range(n - 2, -1, -1):
            x = nums[i]
            best = tree.query(x)
            dp[i] = -nums[i] * i + best
            tree.update(i, dp[i])
        return dp[0]
