class Solution:
    def minNumberOfSeconds(self, mountainHeight: int, workerTimes: List[int]) -> int:
        max_time = 0
        for t in workerTimes:
            candidate = t * (mountainHeight * (mountainHeight + 1) // 2)
            if candidate > max_time:
                max_time = candidate

        low, high = 0, max_time
        while low < high:
            mid = (low + high) // 2
            total_reduction = 0
            for t in workerTimes:
                n_val = (2 * mid) // t
                if n_val == 0:
                    x = 0
                else:
                    disc = 1 + 4 * n_val
                    root = math.isqrt(disc)
                    x = (root - 1) // 2
                total_reduction += x
            if total_reduction >= mountainHeight:
                high = mid
            else:
                low = mid + 1
        return low
