    count = 0

    def dfs(i, j, visited, length):
        nonlocal count
        if length == K + 1:
            count += 1
            return

        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if 0 <= ni < H and 0 <= nj < W:
