                    dfs(ni, nj, visited, length + 1)
                    visited[ni][nj] = False

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                visited = [[False] * W for _ in range(H)]
                visited[i][j] = True
                dfs(i, j, visited, 1)

    print(count)

