import math
from typing import List

class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)

        def lcm(a: int, b: int) -> int:
            return a * b // math.gcd(a, b)

        prefix_gcd = [0] * n
        prefix_lcm = [0] * n
        prefix_gcd[0] = nums[0]
        prefix_lcm[0] = nums[0]
        for i in range(1, n):
            prefix_gcd[i] = math.gcd(prefix_gcd[i-1], nums[i])
            prefix_lcm[i] = lcm(prefix_lcm[i-1], nums[i])

        suffix_gcd = [0] * n
        suffix_lcm = [0] * n
        suffix_gcd[-1] = nums[-1]
        suffix_lcm[-1] = nums[-1]
        for i in range(n-2, -1, -1):
            suffix_gcd[i] = math.gcd(nums[i], suffix_gcd[i+1])
            suffix_lcm[i] = lcm(nums[i], suffix_lcm[i+1])

        best = prefix_gcd[-1] * prefix_lcm[-1]

        for i in range(n):
            if i == 0:
                if n == 1:
                    g, l = 0, 0
                else:
                    g = suffix_gcd[1]
                    l = suffix_lcm[1]
            elif i == n - 1:
                g = prefix_gcd[n-2]
                l = prefix_lcm[n-2]
            else:
                g = math.gcd(prefix_gcd[i-1], suffix_gcd[i+1])
                l = lcm(prefix_lcm[i-1], suffix_lcm[i+1])
            score = g * l
            if score > best:
                best = score

        return best
