from typing import List

class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        n = len(nums)
        choices_list = []
        for x in nums:
            base = x
            op1_val = (x + 1) // 2
            op2_val = x - k if x >= k else None
            cand1 = float('inf')
            if (x + 1) // 2 >= k:
                cand1 = (x + 1) // 2 - k
            cand2 = float('inf')
            if x >= k:
                cand2 = (x - k + 1) // 2
            both_val = min(cand1, cand2)

            choices = []
            choices.append((0, 0, base))
            choices.append((1, 0, op1_val))
            if op2_val is not None:
                choices.append((0, 1, op2_val))
            if both_val != float('inf'):
                choices.append((1, 1, both_val))
            choices_list.append(choices)

        INF = 10**18
        dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0

        for i in range(n):
            new_dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
            for a in range(op1 + 1):
                for b in range(op2 + 1):
                    if dp[a][b] == INF:
                        continue
                    for (da, db, cost_val) in choices_list[i]:
                        na = a + da
                        nb = b + db
                        if na <= op1 and nb <= op2:
                            if dp[a][b] + cost_val < new_dp[na][nb]:
                                new_dp[na][nb] = dp[a][b] + cost_val
            dp = new_dp

        ans = INF
        for a in range(op1 + 1):
            for b in range(op2 + 1):
                if dp[a][b] < ans:
                    ans = dp[a][b]
        return ans
```

