class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        res = []
        for p in nums:
            n = p + 1
            t = 0
            while n % 2 == 0:
                t += 1
                n //= 2
            if t == 0:
                res.append(-1)
            else:
                res.append(p - (1 << (t - 1)))
        return res
