            for j in range(n):
                stay_option = stayScore[i][j] + dp[j]
                best_travel = -10**9
                for prev in range(n):
                    if prev == j:
                        continue
                    candidate = travelScore[prev][j] + dp[prev]
                    if candidate > best_travel:
                        best_travel = candidate
                new_dp[j] = max(stay_option, best_travel)
            dp = new_dp
        return max(dp)
