        prefix = 0
        ans = -10**18
        for i, num in enumerate(nums):
            prefix += num
            r = (i + 1) % k
            if r in min_prefix:
                candidate = prefix - min_prefix[r]
                if candidate > ans:
                    ans = candidate
            if r not in min_prefix:
                min_prefix[r] = prefix
            else:
                if prefix < min_prefix[r]:
                    min_prefix[r] = prefix
        return ans
