class Solution:
    def minOperations(self, n: int, m: int) -> int:
        max_val = 10000
        is_prime = [True] * (max_val + 1)
        is_prime[0] = False
        is_prime[1] = False
        for i in range(2, int(max_val**0.5) + 1):
            if is_prime[i]:
                for j in range(i * i, max_val + 1, i):
                    is_prime[j] = False

        d = len(str(n))
        min_start = 10**(d-1)
        max_end = 10**d - 1

        if is_prime[n] or is_prime[m]:
            return -1

        if n == m:
            return n

        import heapq
        dist = {}
        heap = []
        dist[n] = n
        heapq.heappush(heap, (n, n))

        while heap:
            cost, u = heapq.heappop(heap)
            if cost > dist[u]:
                continue
            if u == m:
                return cost
            neighbors_list = []
            for i in range(d):
                power_i = 10**(d-1-i)
                digit = (u // power_i) % 10
                if digit != 9:
                    v = u + power_i
                    if v < min_start or v > max_end:
                        continue
                    neighbors_list.append(v)
                if digit != 0:
                    if i == 0 and digit == 1:
                        continue
                    v = u - power_i
                    if v < min_start or v > max_end:
                        continue
                    neighbors_list.append(v)
            for v in neighbors_list:
                if is_prime[v]:
                    continue
                new_cost = cost + v
                if v not in dist or new_cost < dist[v]:
                    dist[v] = new_cost
                    heapq.heappush(heap, (new_cost, v))

        return -1
```

