import math
import bisect
from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        value_to_index = {x: i for i, x in enumerate(nums)}

        present_arr = [False] * (threshold + 1)
        for x in nums:
            if x <= threshold:
                present_arr[x] = True

        divisors = [[] for _ in range(threshold + 1)]
        for i in range(1, threshold + 1):
            for j in range(i, threshold + 1, i):
                divisors[j].append(i)

        L = [[] for _ in range(threshold + 1)]
        for g in range(1, threshold + 1):
            for x in range(g, threshold + 1, g):
                if present_arr[x]:
                    L[g].append(x)

        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x: int, y: int) -> None:
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        for a in range(1, threshold + 1):
            if not present_arr[a]:
                continue
            idx_a = value_to_index[a]
            for g in divisors[a]:
                if g > threshold:
                    continue
                max_b_prime = threshold // a
                bound = g * max_b_prime
                if bound > threshold:
                    bound = threshold
                arr = L[g]
                idx_end = bisect.bisect_right(arr, bound)
                for j in range(idx_end):
                    b = arr[j]
                    if b == a:
                        continue
                    b_prime = b // g
                    a_prime = a // g
                    if math.gcd(a_prime, b_prime) == 1:
                        idx_b = value_to_index[b]
                        union(idx_a, idx_b)

        return sum(1 for i in range(n) if find(i) == i)
```

