from typing import List

class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        max_time_for_button = {}
        n = len(events)
        for i in range(n):
            idx, t = events[i]
            prev_time = events[i-1][1] if i > 0 else 0
            interval = t - prev_time
            max_time_for_button[idx] = max(max_time_for_button.get(idx, 0), interval)

        best_button = None
        best_time = -1
        for button, time_val in max_time_for_button.items():
            if time_val > best_time:
                best_button = button
                best_time = time_val
            elif time_val == best_time and button < best_button:
                best_button = button

        return best_button
