class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        runs = []
        count = 1
        n = len(s)
        for i in range(1, n):
            if s[i] == s[i-1]:
                count += 1
            else:
                runs.append(count)
                count = 1
        runs.append(count)

        max_run = max(runs)
        low, high = 1, max_run

        def feasible(M):
            flips = 0
            for L in runs:
                flips += L // (M + 1)
            return flips <= numOps

        while low < high:
            mid = (low + high) // 2
            if feasible(mid):
                high = mid
            else:
                low = mid + 1
        return low
```

