class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        mod = 10**9 + 7
        m = len(grid)
        n = len(grid[0])

        if m == 1 and n == 1:
            return 1 if grid[0][0] == k else 0

        prev = [[0] * 16 for _ in range(n)]
        prev[0][grid[0][0]] = 1

        for j in range(1, n):
            for x in range(16):
                prev_val = x ^ grid[0][j]
                prev[j][x] = prev[j-1][prev_val] % mod

        for i in range(1, m):
            curr = [[0] * 16 for _ in range(n)]
            for x in range(16):
                prev_val = x ^ grid[i][0]
                curr[0][x] = prev[0][prev_val] % mod
            for j in range(1, n):
                for x in range(16):
                    total = prev[j][x ^ grid[i][j]]
                    total = (total + curr[j-1][x ^ grid[i][j]]) % mod
                    curr[j][x] = total
            prev = curr

        return prev[n-1][k] % mod
```
